body:
`JdkZlibDecoder` fails to decode a simple html webpage. I assume its a bug in the netty implementation rather than the JDK itself, but I'm not sure.  Test case below. You will see that the JDK based decoder fails, throwing an `IndexOutOfBoundsException` while the Zlib decoder based on `com.jcraft` works fine. If you replace `MESSAGE` with `MESSAGE2` the JDK tests pass. So, I'm guessing it only happens with larger payloads. It also seems to occur for **both** `gzip` and `deflate` content encoding.

BTW, `MESSAGE` was taken from Tomcat7's default `index.html` page :)

``` java
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.embedded.EmbeddedChannel;
import io.netty.handler.codec.compression.JZlibDecoder;
import io.netty.handler.codec.compression.JdkZlibDecoder;
import io.netty.handler.codec.compression.ZlibDecoder;
import io.netty.handler.codec.compression.ZlibWrapper;
import io.netty.util.CharsetUtil;
import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.zip.DeflaterOutputStream;
import java.util.zip.GZIPOutputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CompressionTest
{
   private static final String MESSAGE = "<!--?xml version=\"1.0\" encoding=\"ISO-8859-1\"?-->\n" +
      "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\n" +
      "<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" lang=\"en\"><head>\n" +
      "    <title>Apache Tomcat</title>\n" +
      "</head>\n" +
      "\n" +
      "<body>\n" +
      "<h1>It works !</h1>\n" +
      "\n" +
      "<p>If you're seeing this page via a web browser, it means you've setup Tomcat successfully. Congratulations!</p>\n" +
      " \n" +
      "<p>This is the default Tomcat home page. It can be found on the local filesystem at: <code>/var/lib/tomcat7/webapps/ROOT/index.html</code></p>\n" +
      "\n" +
      "<p>Tomcat7 veterans might be pleased to learn that this system instance of Tomcat is installed with <code>CATALINA_HOME</code> in <code>/usr/share/tomcat7</code> and <code>CATALINA_BASE</code> in <code>/var/lib/tomcat7</code>, following the rules from <code>/usr/share/doc/tomcat7-common/RUNNING.txt.gz</code>.</p>\n" +
      "\n" +
      "<p>You might consider installing the following packages, if you haven't already done so:</p>\n" +
      "\n" +
      "<p><b>tomcat7-docs</b>: This package installs a web application that allows to browse the Tomcat 7 documentation locally. Once installed, you can access it by clicking <a href=\"docs/\">here</a>.</p>\n" +
      "\n" +
      "<p><b>tomcat7-examples</b>: This package installs a web application that allows to access the Tomcat 7 Servlet and JSP examples. Once installed, you can access it by clicking <a href=\"examples/\">here</a>.</p>\n" +
      "\n" +
      "<p><b>tomcat7-admin</b>: This package installs two web applications that can help managing this Tomcat instance. Once installed, you can access the <a href=\"manager/html\">manager webapp</a> and the <a href=\"host-manager/html\">host-manager webapp</a>.</p><p>\n" +
      "\n" +
      "</p><p>NOTE: For security reasons, using the manager webapp is restricted to users with role \"manager\". The host-manager webapp is restricted to users with role \"admin\". Users are defined in <code>/etc/tomcat7/tomcat-users.xml</code>.</p>\n" +
      "\n" +
      "\n" +
      "\n" +
      "</body></html>";

   private static final String MESSAGE2 = "message";

   @Test
   public void testJdkGZIP2() throws Exception
   {
      ByteBuf data = null;
      ByteBuf deflatedData = null;
      ByteBuf buf = null;
      try
      {
         data = Unpooled.wrappedBuffer(MESSAGE.getBytes(CharsetUtil.UTF_8));
         deflatedData = Unpooled.wrappedBuffer(gzip(MESSAGE));

         EmbeddedChannel chDecoder = new EmbeddedChannel(createJdkDecoder(ZlibWrapper.GZIP));
         chDecoder.writeInbound(deflatedData.copy());
         assertTrue(chDecoder.finish());
         buf = chDecoder.readInbound();
         assertEquals(buf, data);
         assertNull(chDecoder.readInbound());
      }
      finally
      {
         if (data != null)
         {
            data.release();
         }
         if (deflatedData != null)
         {
            deflatedData.release();
         }
         if (buf != null)
         {
            buf.release();
         }
      }
   }

   @Test
   public void testJdkDeflate() throws Exception
   {
      ByteBuf data = null;
      ByteBuf deflatedData = null;
      ByteBuf buf = null;
      try
      {
         data = Unpooled.wrappedBuffer(MESSAGE.getBytes(CharsetUtil.UTF_8));
         deflatedData = Unpooled.wrappedBuffer(deflate(MESSAGE));

         EmbeddedChannel chDecoder = new EmbeddedChannel(createJdkDecoder(ZlibWrapper.ZLIB));
         chDecoder.writeInbound(deflatedData.copy());
         assertTrue(chDecoder.finish());
         buf = chDecoder.readInbound();
         assertEquals(buf, data);
         assertNull(chDecoder.readInbound());
      }
      finally
      {
         if (data != null)
         {
            data.release();
         }
         if (deflatedData != null)
         {
            deflatedData.release();
         }
         if (buf != null)
         {
            buf.release();
         }
      }
   }

   @Test
   public void testZlibGZIP2() throws Exception
   {
      ByteBuf data = null;
      ByteBuf deflatedData = null;
      ByteBuf buf = null;
      try
      {
         data = Unpooled.wrappedBuffer(MESSAGE2.getBytes(CharsetUtil.UTF_8));
         deflatedData = Unpooled.wrappedBuffer(gzip(MESSAGE2));

         EmbeddedChannel chDecoder = new EmbeddedChannel(createZlibDecoder(ZlibWrapper.GZIP));
         chDecoder.writeInbound(deflatedData.copy());
         assertTrue(chDecoder.finish());
         buf = chDecoder.readInbound();
         assertEquals(buf, data);
         assertNull(chDecoder.readInbound());
      }
      finally
      {
         if (data != null)
         {
            data.release();
         }
         if (deflatedData != null)
         {
            deflatedData.release();
         }
         if (buf != null)
         {
            buf.release();
         }
      }
   }

   @Test
   public void testZlibDeflate() throws Exception
   {
      ByteBuf data = null;
      ByteBuf deflatedData = null;
      ByteBuf buf = null;
      try
      {
         data = Unpooled.wrappedBuffer(MESSAGE.getBytes(CharsetUtil.UTF_8));
         deflatedData = Unpooled.wrappedBuffer(deflate(MESSAGE));

         EmbeddedChannel chDecoder = new EmbeddedChannel(createZlibDecoder(ZlibWrapper.ZLIB));
         chDecoder.writeInbound(deflatedData.copy());
         assertTrue(chDecoder.finish());
         buf = chDecoder.readInbound();
         assertEquals(buf, data);
         assertNull(chDecoder.readInbound());
      }
      finally
      {
         if (data != null)
         {
            data.release();
         }
         if (deflatedData != null)
         {
            deflatedData.release();
         }
         if (buf != null)
         {
            buf.release();
         }
      }
   }


   private static byte[] gzip(String message) throws IOException
   {
      ByteArrayOutputStream out = new ByteArrayOutputStream();
      GZIPOutputStream stream = new GZIPOutputStream(out);
      stream.write(message.getBytes(CharsetUtil.UTF_8));
      stream.close();
      return out.toByteArray();
   }

   private static byte[] deflate(String message) throws IOException
   {
      ByteArrayOutputStream out = new ByteArrayOutputStream();
      OutputStream stream = new DeflaterOutputStream(out);
      stream.write(message.getBytes(CharsetUtil.UTF_8));
      stream.close();
      return out.toByteArray();
   }

   private ZlibDecoder createJdkDecoder(ZlibWrapper wrapper)
   {
      return new JdkZlibDecoder(wrapper);
   }

   private ZlibDecoder createZlibDecoder(ZlibWrapper wrapper)
   {
      return new JZlibDecoder(wrapper);
   }
}
